feedbackvariables.text:
[rayList, ptList]: args(ans2)$

incident_candidates2: []$
for r in rayList do (
  if listp(r) and length(r) >= 3 and numberp(r[1]) and numberp(r[2]) and listp(r[3]) and length(r[3]) > 0 then (
    if line_thru(r[1], r[2], B1x2, B1y2, 0.3) then (
      inter: mirror_intersect2(r[1], r[2]),
      if inter # false and on_mirror_segment2(inter[1], xtol) then
        incident_candidates2: append(incident_candidates2, [[r[3], inter[1]]])
    )
  )
)$

reflected_candidates2: []$
for r in rayList do (
  if listp(r) and length(r) >= 3 and numberp(r[1]) and numberp(r[2]) and listp(r[3]) and length(r[3]) > 0 then (
    if line_thru(r[1], r[2], B2x, B2y, 0.3) then (
      inter: mirror_intersect2(r[1], r[2]),
      if inter # false and on_mirror_segment2(inter[1], xtol) then
        reflected_candidates2: append(reflected_candidates2, [[r[3], inter[1]]])
    )
  )
)$

any_attempt2: is(length(incident_candidates2) > 0 or length(reflected_candidates2) > 0)$

all_pairs2: []$
for ic in incident_candidates2 do (
  for rc in reflected_candidates2 do (
    Ix: ic[2],
    Ix2: rc[2],
    if abs(Ix - Ix2) < xtol then (
      inc_pieces: ic[1],
      refl_pieces: rc[1],
      xNear: min(B1x2, Ix), xFar: max(B1x2, Ix),
      dirsign1: if Ix >= B1x2 then 1 else -1,
      xBeyond1: Ix + dirsign1*1.0,
      inc_real_ok: is(eff_status(status_covering_x(inc_pieces, xNear + xtol, xtol)) = 1
                and eff_status(status_covering_x(inc_pieces, xFar - xtol, xtol)) = 1),
      inc_absent_ok: is(status_covering_x(inc_pieces, xBeyond1, xtol) = -1),
      inc_full: is(inc_real_ok and inc_absent_ok),
      xRNear: min(Ix, B2x) + xtol, xRFar: max(Ix, B2x) - xtol,
      refl_full: is(eff_status(status_covering_x(refl_pieces, xRNear, xtol)) = 1
                and eff_status(status_covering_x(refl_pieces, xRFar, xtol)) = 1),
      inc_score: if inc_full then 1 else GEOM_WEIGHT,
      refl_score: if refl_full then 1 else GEOM_WEIGHT,
      pair_score: (inc_score + refl_score)/2,
      all_pairs2: append(all_pairs2, [[Ix, pair_score]])
    )
  )
)$

accepted2: []$
for pr in all_pairs2 do (
  is_dup: false,
  for a in accepted2 do (if abs(a[1] - pr[1]) < xtol then is_dup: true),
  if not is_dup and length(accepted2) < 2 then accepted2: append(accepted2, [pr])
)$

nb_accepted2: length(accepted2)$
nb_bonnes2: if nb_accepted2 = 0 then 0 elseif nb_accepted2 = 1 then accepted2[1][2] else accepted2[1][2] + accepted2[2][2]$
score_rayons2: min(nb_bonnes2/2, 1)$

have2b: is(nb_accepted2 >= 2)$

c_pointB2: is(found_point(ptList, B2x, B2y, 0.3))$
c_pointA2: is(found_point(ptList, A2x, A2y, 0.3))$
